namespace AkilliKisayol {
 public static class FeatureTests {
  static void Pump(Task task){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(15)};var limit=DateTime.UtcNow.AddSeconds(12);timer.Tick+=(s,e)=>{if(task.IsCompleted||DateTime.UtcNow>limit){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);if(!task.IsCompleted)throw new TimeoutException("Özellik testi zaman aşımı.");task.GetAwaiter().GetResult();}
  public static void Unit(Action<bool,string> check){
   var state=new State();var shared=new Binding{Name="Shared",Key=119,Kind="Web address",Target="https://example.com"};var work=shared.Copy();work.Id="work-binding";work.Name="Work";work.ProfileId="work";var game=shared.Copy();game.Id="game-binding";game.Name="Game";game.ProfileId="game";state.Bindings.AddRange(new[]{shared,work,game});
   check(!Rules.Conflicts(work,new[]{game}).Any(),"Farklı profil atamaları aynı tuşu kullanabilir");check(Rules.Conflicts(shared,new[]{work}).All(c=>!c.StartsWith("CONFLICT")),"Ortak ve profile özel atamalar öncelik taşır");
   check(Rules.Resolve(Profiles.Effective(state),0,119,"")==work,"İş profilinde doğru atama seçilir");state.ActiveProfileId="game";check(Rules.Resolve(Profiles.Effective(state),0,119,"")==game,"Oyun profilinde aynı tuş diğer atamayı seçer");
   var typing=shared.Copy();typing.Id="typing";typing.Key=65;state.Bindings.Add(typing);check(!Profiles.Effective(state).Contains(typing),"Oyun profili değiştiricisiz genel yazı tuşunu kapatır");typing.Mods=2;check(Profiles.Effective(state).Contains(typing),"Oyun profili Ctrl kombinasyonlarını korur");typing.Mods=0;typing.AppPath=@"C:\Apps\editor.exe";check(Profiles.Effective(state).Contains(typing),"Oyun profili uygulamaya özel tuşu korur");
   string root=Path.Combine(Path.GetTempPath(),"FeatureTests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
    string brave=Path.Combine(root,"brave.exe"),other=Path.Combine(root,"Other.exe"),spotify=Path.Combine(root,"Spotify.exe");foreach(string path in new[]{brave,other,spotify})File.WriteAllText(path,"");
    var preferences=new UserPreferences{Browser=brave,MediaApp=spotify};var request=new LlmRequest{Prompt="Open https://example.com when I press F9",Applications=new List<string>{brave,other,spotify},Preferences=preferences};
    check(AppIntegration.Target(request)==brave,"Genel web isteği hatırlanan tarayıcıyı kullanır");request.TargetApp=other;check(AppIntegration.Target(request)==other,"Elle seçilen hedef tercihten önce gelir");request.TargetApp="";request.Prompt="Open https://example.com in Other app when I press F9";check(AppIntegration.Target(request)==other,"Prompttaki açık uygulama adı tercihten önce gelir");
    request.Prompt="Open https://example.com in Firefox when I press F9";check(AppIntegration.Target(request)=="","Kayıtsız açık hedef yerine tercih sessizce seçilmez");
    request.Prompt="Open this playlist https://open.spotify.com/playlist/ABC when I press F9";check(AppIntegration.Target(request)==spotify,"Playlist için müzik tercihi kullanılır");
    check(!BrowserSupport.MentionedApps(request).Any(),"URL içindeki uygulama markası açık hedef seçimi sayılmaz");request.Prompt="Open this playlist https://open.spotify.com/playlist/ABC in the browser when I press F9";check(AppIntegration.Target(request)==brave,"Prompttaki tarayıcı isteği müzik tercihinden önce gelir");
    var learned=new Binding{Kind="Workflow",Prompt="Open https://docs.example.org/page in Other",Steps=new List<ActionStep>{new ActionStep{Kind="Open content",AppPath=other,Text="https://docs.example.org/page"}}};check(PreferenceMemory.Learn(preferences,learned),"Kaydedilen hedef tercihi alan adıyla öğrenilir");request.Prompt="Open https://docs.example.org/another when I press F9";check(AppIntegration.Target(request)==other,"Öğrenilen alan adı sonraki isteğe uygulanır");preferences.LearnOnSave=false;learned.Steps[0].AppPath=brave;check(!PreferenceMemory.Learn(preferences,learned)&&preferences.Rules.Single().AppPath==other,"Otomatik hatırlama kapatılabilir");
    request.Prompt="Open https://docs.example.org.evil.test when I press F9";check(AppIntegration.Target(request)==brave,"Alan adı tercihi benzer görünen başka alan adına uygulanmaz");
    state.Preferences=preferences;state.GuideEnabled=false;state.GuideHoldKey=161;string file=Path.Combine(root,"state.json");Storage.Write(state,file);var restored=Storage.Read(file);check(restored.ActiveProfileId=="game"&&restored.Profiles.Count==3&&restored.Preferences.Rules.Single().AppPath==other&&!restored.GuideEnabled&&restored.GuideHoldKey==161,"Profil, tercihler ve yardım ayarları kalıcı saklanır");
    File.WriteAllText(file,"{\"Bindings\":[],\"History\":[],\"Dark\":true}");restored=Storage.Read(file);check(restored.Profiles.Count==3&&restored.Preferences!=null&&restored.GuideEnabled&&restored.GuideHoldKey==163,"Eski ayarlar yeni özelliklere kayıpsız geçer");
    var macro=new Binding{Name="Macro",Key=119,Kind="Workflow",IsMacro=true,Steps=Enumerable.Range(0,25).Select(i=>new ActionStep{Kind="Key",Key=65}).ToList()};check(Rules.Validate(macro,new Binding[0])==null,"Kaydedilen makro model planının 20 adım sınırından bağımsızdır");macro.Steps.Add(new ActionStep{Kind="Mouse click",X=10,Y=15,WindowWidth=300,WindowHeight=200});check(Rules.Validate(macro,new Binding[0])==null,"Kayıtlı fare konumu doğrulanır");macro.Steps.Last().X=400;check(Rules.Validate(macro,new Binding[0])!=null,"Pencere dışındaki fare kaydı reddedilir");
    macro.Steps.Last().X=10;state.Bindings.Add(macro);Storage.Write(state,file);restored=Storage.Read(file);check(restored.Bindings.Last().IsMacro&&restored.Bindings.Last().Steps.Last().WindowWidth==300,"Makro türü ve konum bilgileri kalıcı korunur");
   }finally{foreach(string file in Directory.GetFiles(root))File.Delete(file);Directory.Delete(root);}
   var rows=GuideEntries.Build(state,new SystemShortcut[0],"");check(rows.Any(r=>r.Name=="Game")&&!rows.Any(r=>r.Name=="Work"||r.Name=="Shared"),"Yardım paneli yalnızca etkin ve öncelikli profil atamasını gösterir");
  }
  public static void Ui(MainWindow owner,KeyboardEngine keyboard,Action<bool,string> check,Action<Window,string> screenshot,Action<string> skip){
   var data=new State();var prefs=new PreferencesWindow(data.Preferences,new[]{System.Reflection.Assembly.GetExecutingAssembly().Location},p=>true){Owner=owner};prefs.Show();check(prefs.IsVisible,"Tercih yönetim ekranı açılır");screenshot(prefs,"preferences-preview.png");prefs.Close();
   check(owner.ProfileForTest("game")&&owner.ProfileForTest("work"),"Gerçek ana pencere profil değişimini kaydeder ve uygular");
   var profiles=new ProfilesWindow(data,(p,a)=>true){Owner=owner};profiles.Show();check(profiles.ProfileCountForTest==3,"İş/Oyun/Çalışma profilleri yönetimde gösterilir");screenshot(profiles,"profiles-preview.png");profiles.Close();
   UserPreferences savedPreferences=null;string appPath=System.Reflection.Assembly.GetExecutingAssembly().Location;var savePrefs=new PreferencesWindow(data.Preferences,new[]{appPath},p=>{savedPreferences=p;return true;}){Owner=owner};Application.Current.Dispatcher.BeginInvoke(new Action(()=>savePrefs.SaveForTest(appPath)));check(savePrefs.ShowDialog()==true&&savedPreferences.Browser==appPath,"Tercihler ekranının kaydet düğmesi seçilen uygulamayı iletir");
   data.Bindings.Add(new Binding{Id="membership",Name="Profil ataması",Key=119,ProfileId="work"});List<ProfileAssignment> savedAssignments=null;var saveProfiles=new ProfilesWindow(data,(p,a)=>{savedAssignments=a;return true;}){Owner=owner};Application.Current.Dispatcher.BeginInvoke(new Action(()=>saveProfiles.SaveForTest("membership","game")));check(saveProfiles.ShowDialog()==true&&savedAssignments.Single().ProfileId=="game","Profil ekranının kaydet düğmesi atama grubunu iletir");
   var macro=new MacroWindow(keyboard,new Binding[0],data.Profiles,"work",()=>new SystemShortcut[0]){Owner=owner};macro.Show();check(!macro.CanSaveForTest,"Boş kayıt makro olarak kaydedilemez");macro.StepsForTest(new[]{new ActionStep{Kind="Key",Key=65}});check(macro.CanSaveForTest,"Kaydedilen makro önizlemesi kayda hazırdır");screenshot(macro,"macro-preview.png");macro.Close();
   var guideRows=new[]{new GuideRow{Combo="Del + 5",Name="YouTube’u Brave ile aç",Source="Atamam • Genel"},new GuideRow{Combo="F9",Name="Spotify playlist",Source="Atamam • Genel"},new GuideRow{Combo="Ctrl + C",Name="Copy",Source="Known default"}};var guide=new GuideWindow("Brave • İş",guideRows);owner.Activate();Native.ActivateWindow(new WindowInteropHelper(owner).Handle);Application.Current.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));IntPtr foreground=Native.GetForegroundWindow();guide.Show();Application.Current.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));check(Native.GetForegroundWindow()==foreground,"Yardım paneli açılırken ön plan odağı değişmez");screenshot(guide,"shortcut-guide-preview.png");guide.Close();
   Engine(keyboard,owner,check);Recorder(keyboard,owner,check,skip);
  }
  static void Engine(KeyboardEngine keyboard,Window owner,Action<bool,string> check){
   bool paused=keyboard.Paused;keyboard.Paused=false;var binding=new Binding{Key=119,Name="Pending"};keyboard.Bindings=()=>new List<Binding>{binding};int fires=0;keyboard.Fire=(b,w)=>fires++;keyboard.Handle(new Native.Keyboard{vk=119});keyboard.ResetPending();keyboard.Handle(new Native.Keyboard{vk=119,flags=128});keyboard.FlushForTest();check(fires==0,"Profil değişiminde eski bekleyen eylem çalışmaz");
   int observed=0;keyboard.PhysicalInput+=e=>observed++;keyboard.Handle(new Native.Keyboard{vk=65,flags=16});check(observed==0,"Sentetik klavye girdisi makro ve yardım gözlemcisine sızmaz");
   var state=new State();using(var guide=new ShortcutGuide(keyboard,()=>state,()=>new SystemShortcut[0])){guide.OpenForTest(new WindowInteropHelper(owner).Handle);check(guide.VisibleForTest,"Yardım paneli oluşturulabilir");keyboard.Handle(new Native.Keyboard{vk=163});keyboard.Handle(new Native.Keyboard{vk=67});check(!guide.VisibleForTest,"Ctrl ile başka tuşa basılınca yardım paneli kapanır");keyboard.Handle(new Native.Keyboard{vk=67,flags=128});keyboard.Handle(new Native.Keyboard{vk=163,flags=128});}keyboard.Paused=paused;
  }
  static void Recorder(KeyboardEngine keyboard,Window owner,Action<bool,string> check,Action<string> skip){
   var target=new Window{Title="Macro fixture",Width=440,Height=280,Topmost=true,Owner=owner,WindowStartupLocation=WindowStartupLocation.CenterScreen};var panel=new StackPanel();var text=new TextBox{Height=45};var button=new Button{Content="Macro test button",Height=45};AutomationProperties.SetAutomationId(button,"macro-button");int clicks=0;var mouseClicked=new TaskCompletionSource<bool>();button.Click+=(s,e)=>{clicks++;if(clicks>=2)mouseClicked.TrySetResult(true);};panel.Children.Add(text);panel.Children.Add(button);target.Content=panel;target.Show();IntPtr handle=new WindowInteropHelper(target).Handle;
   try{
    bool paused=keyboard.Paused;using(var recorder=new MacroRecorder(keyboard)){recorder.AllowOwnProcess=true;recorder.Start(false);check(keyboard.Paused&&recorder.Recording,"Makro sırasında kişisel tetikleyiciler duraklatılır");recorder.FeedForTest(new ActionStep{Kind="Key",Key=65},handle,0);recorder.FeedForTest(new ActionStep{Kind="Key",Key=66},handle,450);var task=recorder.StopAsync();Pump(task);var steps=task.GetAwaiter().GetResult();check(steps.Count==4&&steps[0].Kind=="Focus"&&steps[2].Kind=="Wait"&&steps[2].Delay==450,"Kayıt sırası, odak ve bekleme süreleri korunur");check(keyboard.Paused==paused&&!recorder.Recording,"Kayıt bitince önceki motor durumu geri gelir");}
    using(var recorder=new MacroRecorder(keyboard)){recorder.Start(false);recorder.ObserveForTest(new PhysicalKey{Key=65,Window=handle});var stop=recorder.StopAsync();Pump(stop);check(stop.Result.Count==0,"Uygulamanın kendi ekranındaki girişler kaydedilmez");}
    using(var recorder=new MacroRecorder(keyboard)){recorder.AllowOwnProcess=true;recorder.Start();var rect=AutomationElement.FromHandle(handle).Current.BoundingRectangle;var mouse=new Native.MouseEvent{Point=new Native.Point{X=(int)rect.Left+30,Y=(int)rect.Top+100}};recorder.MouseForTest(0x201,mouse,handle,0,0);mouse.Point.X+=60;recorder.MouseForTest(0x202,mouse,handle,0,250);var stop=recorder.StopAsync();Pump(stop);check(stop.Result.Last().Kind=="Mouse drag"&&stop.Result.Last().X2>stop.Result.Last().X,"Gerçek fare kancası açılır ve sürükleme uçları kayda dönüşür");}
    using(var recorder=new MacroRecorder(keyboard)){recorder.Start(false);check(recorder.ObserveForTest(new PhysicalKey{Key=121,Window=handle}),"F10 durdurma tuşu kaynak uygulamaya iletilmez");var stop=recorder.StopAsync();Pump(stop);check(stop.Result.Count==0,"Durdurma tuşu makronun içine kaydedilmez");}
    target.Activate();Native.ActivateWindow(handle);text.Focus();Application.Current.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));if(Native.GetForegroundWindow()!=handle){skip("Makro oynatma: Windows test penceresine ön plan izni vermedi; başka pencereye giriş gönderilmedi.");return;}
    var focused=Actions.Focus(Native.ProcessPath(handle),CancellationToken.None,Native.WindowTitle(handle),Native.WindowClass(handle));check(focused.IsCompleted&&focused.GetAwaiter().GetResult()==handle,"Already foreground target avoids redundant activation and 100 ms wait");var workflow=new Binding{IsMacro=true,Kind="Workflow",Steps=new List<ActionStep>{new ActionStep{Kind="Key",Key=65},new ActionStep{Kind="Click element",AutomationId="macro-button",Text="Macro test button",ControlType=ControlType.Button.Id}}};Pump(Actions.RunSteps(workflow,handle));check(text.Text.Equals("a",StringComparison.OrdinalIgnoreCase)&&clicks==1,"Makro gerçek tuş ve erişilebilir öğe tıklamasıyla oynatılır");
    var windowRect=AutomationElement.FromHandle(handle).Current.BoundingRectangle;var bounds=AutomationElement.FromHandle(handle).FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,"macro-button")).Current.BoundingRectangle;var click=new ActionStep{Kind="Mouse click",X=bounds.Left+bounds.Width/2-windowRect.Left,Y=bounds.Top+bounds.Height/2-windowRect.Top,WindowWidth=windowRect.Width,WindowHeight=windowRect.Height};Pump(Actions.RunSteps(new Binding{IsMacro=true,Steps=new List<ActionStep>{click}},handle));Pump(Task.WhenAny(mouseClicked.Task,Task.Delay(1500)));check(clicks==2,"Konuma bağlı fare adımı gerçek test düğmesine tıklar ("+clicks+")");
    text.Clear();text.Focus();using(var recorder=new MacroRecorder(keyboard)){recorder.AllowOwnProcess=true;recorder.Start(false);recorder.ObserveForTest(new PhysicalKey{Key=66,Window=handle});var stop=recorder.StopAsync();Pump(stop);Pump(Actions.RunSteps(new Binding{IsMacro=true,Steps=stop.Result},handle));check(text.Text.Equals("b",StringComparison.OrdinalIgnoreCase),"Kaydedilen odak ve tuş dizisi değiştirilmeden tekrar oynatılır");}
   }finally{target.Close();}
  }
  public static int Real(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"features-model-test.json");var results=new List<object>();using(var model=new LocalLlm())try{
   var state=Storage.Read(Storage.FilePath);string brave=state.ApplicationPaths.First(p=>Path.GetFileName(p).Equals("brave.exe",StringComparison.OrdinalIgnoreCase)),spotify=state.ApplicationPaths.First(p=>Path.GetFileName(p).Equals("spotify.exe",StringComparison.OrdinalIgnoreCase));
   var preferences=new UserPreferences{Browser=brave,MediaApp=spotify,Rules=new List<AppPreference>{new AppPreference{Match="open.spotify.com",AppPath=spotify}}};
   var cases=new[]{new{prompt="Open https://example.com when I press F6.",target=brave},new{prompt="Open this playlist https://open.spotify.com/playlist/0123456789ABCDEFGHIJKL when I press F9.",target=spotify}};
   foreach(var test in cases){var request=new LlmRequest{Prompt=test.prompt,SelectedApp="",TargetApp="",Trigger="",Applications=state.ApplicationPaths,ModelPath=state.ModelPath,Preferences=preferences};var plan=model.AnalyzeAsync(request,m=>{},CancellationToken.None).GetAwaiter().GetResult();bool correct=plan.Ready&&(plan.Binding.Kind=="Browser website"?Rules.SameApp(plan.Binding.BrowserPath,test.target):plan.Binding.Steps!=null&&plan.Binding.Steps.Any(s=>s.Kind=="Open content"&&Rules.SameApp(s.AppPath,test.target)));results.Add(new{prompt=test.prompt,passed=correct,binding=plan.Binding,errors=plan.Errors,response=model.LastResponse});if(!correct)throw new InvalidDataException("Hatırlanan tercih model tarafından uygulanmadı.");}
   File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",results=results}));return 0;
  }catch(Exception e){File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="FAIL",error=e.ToString(),response=model.LastResponse,results=results}));return 1;}}
 }
